import json
import itertools

def solve_puzzle():
    # Input variables based on the puzzle
    houses = [1, 2]  # 1 is leftmost, 2 is rightmost
    categories_order = ["Name", "vacation"]
    values = {
        "Name": ["Arnold", "Eric"],
        "vacation": ["beach", "mountain"],
    }

    # Helper to evaluate constraints
    def satisfies_constraints(assignment):
        # Constraint 1: Arnold is somewhere to the right of the person who loves beach vacations.
        def pos_of(category, value):
            try:
                return assignment[category].index(value)
            except ValueError:
                return None

        pos_arnold = pos_of("Name", "Arnold")
        pos_beach = pos_of("vacation", "beach")
        if pos_arnold is None or pos_beach is None:
            return False
        if not (pos_arnold > pos_beach):
            return False

        return True

    # Generate all possible assignments
    perms = {cat: list(itertools.permutations(vals)) for cat, vals in values.items()}

    solutions = []

    # Cartesian product over all category permutations
    for name_perm in perms["Name"]:
        for vacation_perm in perms["vacation"]:
            assignment = {
                "Name": list(name_perm),
                "vacation": list(vacation_perm),
            }
            if satisfies_constraints(assignment):
                solutions.append(assignment)

    if not solutions:
        raise RuntimeError("No solution found.")
    # If multiple solutions found, select the first (should be unique for this puzzle)
    solution = solutions[0]

    header = ["House"] + categories_order
    rows = []
    for i, house in enumerate(houses):
        row = [str(house)]
        for cat in categories_order:
            row.append(solution[cat][i])
        rows.append(row)

    return {
        "solution": {
            "header": header,
            "rows": rows
        }
    }

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, indent=2))
